# Bandwidth-delay product: bytes that must be in flight to fill the pipe.
# Throughput <= window / RTT. If window < BDP, window is the cap.
def max_throughput_mbps(window_bytes: int, rtt_ms: float) -> float:
    return (window_bytes * 8 / (rtt_ms / 1000.0)) / 1e6

def bdp_bytes(bandwidth_mbps: float, rtt_ms: float) -> int:
    return int(bandwidth_mbps * 1e6 * (rtt_ms / 1000.0) / 8)

# 64KB window, 100ms RTT -> ~5.2 Mbps cap regardless of link
print(max_throughput_mbps(64 * 1024, 100))
# 1 Gbps at 100ms RTT needs ~12.5 MB in flight
print(bdp_bytes(1000, 100))
